parameters.jsCode:
const s = $('Write settings').first().json;
const p = $json;
const decode = t => String(t || '').replace(/&nbsp;/g, ' ').replace(/&quot;/g, '"').replace(/&#39;|&rsquo;/g, "'")
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&');
const clean = t => decode(t).replace(/[{}]/g, '').replace(/\s+/g, ' ').trim();
const text = h => clean(String(h || '').replace(/<[^>]+>/g, ' '));
const re = t => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

// Where the intro ends: at the first heading, list, table or other block named in intro_ends_at.
// A wrapper around the whole description is looked inside, and a short label paragraph
// right before the block ("Specifications:", or all bold) stays with the block it introduces.
const splitIntro = (html, tags) => {
  let pre = '', post = '', body = String(html || '');
  for (;;) {
    const m = body.match(/^\s*(<(div|section|article)\b[^>]*>)([\s\S]*)(<\/\2>)\s*$/i);
    if (!m) break;
    let depth = 0, whole = true;
    for (const x of m[3].matchAll(new RegExp('<(/?)' + m[2] + '\\b', 'gi'))) {
      depth += x[1] ? -1 : 1;
      if (depth < 0) { whole = false; break; }
    }
    if (!whole || depth !== 0) break;
    pre += m[1]; post = m[4] + post; body = m[3];
  }
  let at = body.search(new RegExp('<(' + tags.join('|') + ')(?=[\\s>/])', 'i'));
  if (at < 0) return { pre, intro: body, rest: '', post, found: false };
  const before = body.slice(0, at);
  const lastP = before.search(/<p\b[^>]*>(?:(?!<p\b)[\s\S])*$/i);
  if (lastP >= 0) {
    const para = before.slice(lastP).trim();
    const words = para.replace(/<[^>]+>/g, '').trim();
    if (words.length <= 80 && (/:$/.test(words) || /^<p\b[^>]*>\s*<(strong|b)\b[\s\S]*<\/(strong|b)>\s*(<\/p>)?$/i.test(para))) at = lastP;
  }
  return { pre, intro: body.slice(0, at), rest: body.slice(at), post, found: true };
};

// One "Label: value" line per metafield. Standard product attributes are metaobject references,
// so use their display names: a raw ID means nothing to the model.
const valueOf = m => {
  const refs = ((m.references && m.references.nodes) || []).map(r => r.displayName).filter(Boolean);
  if (refs.length) return refs.join(', ');
  if (m.reference && m.reference.displayName) return m.reference.displayName;
  let v = m.value;
  try {
    const j = JSON.parse(v);
    if (Array.isArray(j)) v = j.join(', ');
    else if (j && j.value !== undefined) v = j.value + (j.unit ? ' ' + String(j.unit).toLowerCase().replace(/_/g, ' ') : '');
  } catch (e) { /* plain text */ }
  return clean(v);
};
const lines = [];
for (const m of p.metafields.nodes) {
  if (m.namespace === s.manufacturer_url_namespace && m.key === s.manufacturer_url_key) continue;
  if (/rich_text|json|file_reference|url|collection_reference|product_reference/.test(m.type)) continue;
  const v = valueOf(m);
  if (!v || v.startsWith('gid://') || v.length > 200) continue;
  const line = '- ' + clean(m.definition ? m.definition.name : m.key) + ': ' + v;
  if (!lines.includes(line)) lines.push(line);
}
if (!p.hasOnlyDefaultVariant) for (const o of p.options) lines.push('- ' + clean(o.name) + ': ' + o.values.map(clean).join(', '));

// The intro is what gets replaced; lists and tables below it are facts too
const parts = splitIntro(p.descriptionHtml, s.intro_ends_at);
const rows = [...new Set([...parts.rest.matchAll(/<(li|tr)\b[^>]*>([\s\S]*?)<\/\1>/gi)]
  .map(m => text(m[2].replace(/<\/t[dh]>\s*<t[dh][^>]*>/gi, ': '))).filter(r => r.length > 1 && r.length <= 200))].slice(0, 40);
const facts = lines.length + rows.length;

// Supplier copy is a source of facts, not of wording: drop warranty, delivery and sales sentences
const strip = new RegExp(s.strip_patterns.map(re).join('|'), 'i');
const prose = text((parts.intro + parts.rest.replace(/<(li|tr|h\d)\b[^>]*>[\s\S]*?<\/\1>/gi, ' ')).replace(/<\/(p|div)>/gi, '. '));
const supplier = prose.split(/(?<=[.!?])\s+/).filter(x => x.replace(/[.\s]/g, '') && !strip.test(x)).join(' ').replace(/\.\s*\./g, '.').slice(0, s.max_chars_supplier);

const intro = text(parts.intro);
const thin = facts < s.min_facts;
return { json: {
  product_id: p.id, title: clean(p.title), vendor: clean(p.vendor),
  category: p.productType || (p.category && p.category.name) || 'default',
  image: p.featuredMedia && p.featuredMedia.preview && p.featuredMedia.preview.image ? p.featuredMedia.preview.image.url : '',
  admin_url: 'https://' + s.store_domain + '/admin/products/' + p.id.split('/').pop(),
  preview_url: p.onlineStorePreviewUrl || '',
  manufacturer_url: (p.manufacturerUrl && p.manufacturerUrl.value) || '',
  specs: lines.join('\n'), desc_specs: rows.map(r => '- ' + r).join('\n'), supplier_copy: supplier,
  old_intro: intro.slice(0, 500),
  intro_mode: !parts.found ? 'replace_all' : intro ? 'replace_intro' : 'insert',
  kept_preview: text(parts.rest).slice(0, 80),
  facts, status: thin ? 'needs_specs' : 'writing',
  error: thin ? 'only ' + facts + ' spec lines; add specs and tag it again' : ''
} };

const p = $('Build the facts').first().json;
const rows = $input.all().map(i => i.json).filter(r => r.text);
// Up to three from the same product type, newest first; the seeds when the type has none yet
const same = rows.filter(r => r.category === p.category).slice(0, 3);
const pick = same.length ? same : rows.filter(r => r.source === 'seed').slice(0, 2);
const examples = pick.map((r, i) => 'Example ' + (i + 1) + ' (' + r.category + '):\n' + r.text.replace(/[{}]/g, '')).join('\n\n');
return [{ json: { ...p, examples } }];

const s = $('Write settings').first().json;
const url = $('Collect examples').first().json.manufacturer_url;
const md = String($input.first().json.markdown || '');
const re = t => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const SPEC = new RegExp('\\b(' + s.spec_words.map(re).join('|') + ')', 'gi'); // word starts: 'port' isn't 'Support'

// Drop image lines and lines that are only links (menus); keep link text, lose the URL
const cleaned = md.split('\n').filter(l => {
  const t = l.trim().replace(/\\([\[\]])/g, '$1');
  return !/^!\[/.test(t) && !/^([*\-+]|\d+\.)?\s*(\[[^\]]*\](\([^)]*\))?\s*)+$/.test(t);
}).join('\n').replace(/!\[[^\]]*\]\([^)]*\)/g, '').replace(/\]\([^)]*\)/g, ']').replace(/\n{3,}/g, '\n\n');

const focus = (text, budget) => {
  if (text.length <= budget) return text;
  const pieces = [];
  for (const para of text.split(/\n{2,}/)) {
    if (pieces.length && pieces[pieces.length - 1].length + para.length < 700) pieces[pieces.length - 1] += '\n\n' + para;
    else pieces.push(para);
  }
  const scored = pieces.map((p, i) => ({ i, p,
    sc: (((p.match(SPEC) || []).length * 3 + (p.match(/\d/g) || []).length / 15)
      - ((p.match(/\]/g) || []).length > 8 ? 5 : 0)) / Math.max(1, Math.sqrt(p.length / 300)) }))
    .sort((a, b) => b.sc - a.sc);
  const keep = []; let used = 0;
  for (const c of scored) { if (c.sc <= 0 || used + c.p.length > budget) continue; keep.push(c); used += c.p.length; }
  return keep.sort((a, b) => a.i - b.i).map(c => c.p).join('\n...\n');
};

const focused = focus(cleaned, s.max_chars_manufacturer).replace(/[{}]/g, '').trim();
return [{ json: { url, focused_text: focused, fetched_at: new Date().toISOString(), status: focused ? 'ok' : 'empty' } }];

const s = $('Write settings').first().json;
const p = $('Build the prompt').first().json;
const r = $input.first().json;
const reply = String(r.text || '').replace(/<think>[\s\S]*?<\/think>/g, '').trim();

const re = t => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const fix = t => t.replace(/[\u2010\u2011\u2012\u00AD]/g, '-').replace(/\s*[\u2013\u2014]\s*/g, ', ').replace(/[ \t]+/g, ' ').trim();
const squash = t => String(t).toLowerCase().replace(/[\s\-.]/g, '');

// Paragraphs split on blank lines; stray bullets, headings and bold removed; dashes become commas
const paras = reply.split(/\n\s*\n/)
  .map(x => fix(x.replace(/^\s*(#+|[-*]|\d+\.)\s+/gm, '').replace(/\*\*/g, '').replace(/\n/g, ' ')))
  .filter(Boolean);
const plain = paras.join(' ');
const words = plain.split(/\s+/).filter(Boolean).length;

// Standards in always_ok pass even when the sources don't name them
let scan = plain;
const loose = t => t.split(/[-.\s]+/).map(re).join('[-.\\s]?');
for (const t of s.always_ok) scan = scan.replace(new RegExp('(^|[^A-Za-z0-9])' + loose(t) + '(?![A-Za-z0-9])', 'gi'), '$1 ');

// Codes such as IP67 match whole, ignoring spaces, hyphens and dots; every other number must be in the
// sources as written (4.0 counts as 4, but 79 isn't 79.7 and 5 isn't the 5 in 5.4)
const ctx = p.context.replace(/(\d),(?=\d{3})/g, '$1');
const ctxN = ctx.replace(/(\d)\.0+(?![0-9])/g, '$1');
const ctxS = squash(ctx);
const codes = [];
scan = scan.replace(/(\d),(?=\d{3})/g, '$1')
  .replace(/\b[A-Za-z]+-?\.?\d+(?:\.\d+)*[A-Za-z]*\b/g, m => { codes.push(m); return ' '; });
const nums = [...new Set(scan.match(/\d+(?:\.\d+)?/g) || [])];
const badNums = nums.filter(n => !new RegExp('(^|[^0-9.])' + re(n.replace(/\.0+$/, '')) + '(?![0-9]|[.,][0-9])').test(ctxN));
const badCodes = [...new Set(codes)].filter(c => !ctxS.includes(squash(c)));

const banned = s.banned_phrases.filter(b => new RegExp('\\b' + re(b) + '\\b', 'i').test(plain));
const flags = [];
if (badNums.length || badCodes.length) flags.push('numbers not in sources: ' + [...badNums, ...badCodes].join(', '));
if (banned.length) flags.push('phrases: ' + banned.join(', '));

let error = '';
if (r.error) error = 'model call failed: ' + String(r.error.message || r.error).slice(0, 200);
else if (!paras.length) error = 'no text in the reply';
else if (words < s.min_words) error = 'too short (' + words + ' words)';

return [{ json: { ...p,
  draft_text: paras.join('\n\n'), words, flags: flags.join('; '), model: s.model,
  status: error ? 'failed' : 'pending', error
} }];

