const raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
const h = $input.first().json.headers;
if (Math.abs(Date.now() / 1000 - Number(h['x-slack-request-timestamp'])) > 300) throw new Error('Stale request');
const field = raw.split('&').find(kv => kv.startsWith('payload=')) || ''; // no URLSearchParams in the Code node
const b = JSON.parse(decodeURIComponent(field.slice(8).replace(/\+/g, ' ')));
const a = b.actions[0];
if (!a.action_id.startsWith('desc_')) return []; // Edit in Shopify and Preview are links: nothing to do

// The edit box arrives with the button click; tags are stripped because Push escapes the text
const box = ((((b.state || {}).values || {}).field_description || {}).edit_description) || {};
const text = String(box.value || '').replace(/<[^>]*>/g, '').replace(/\r/g, '').trim();
return [{ json: {
  base: `v0:${h['x-slack-request-timestamp']}:${raw}`, expected: h['x-slack-signature'],
  action: a.action_id.replace('desc_', ''), product_id: a.value, text,
  user: b.user.username, channel: b.channel.id, ts: b.message.ts
} }];

