const s = $('Push settings').first().json;
const d = $('Only this product').item.json;
const product = ($json.data && $json.data.product) || {};
const live = String(product.descriptionHtml || '');
const esc = t => String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// Where the intro ends: at the first heading, list, table or other block named in intro_ends_at.
// A wrapper around the whole description is looked inside, and a short label paragraph
// right before the block ("Specifications:", or all bold) stays with the block it introduces.
const splitIntro = (html, tags) => {
  let pre = '', post = '', body = String(html || '');
  for (;;) {
    const m = body.match(/^\s*(<(div|section|article)\b[^>]*>)([\s\S]*)(<\/\2>)\s*$/i);
    if (!m) break;
    let depth = 0, whole = true;
    for (const x of m[3].matchAll(new RegExp('<(/?)' + m[2] + '\\b', 'gi'))) {
      depth += x[1] ? -1 : 1;
      if (depth < 0) { whole = false; break; }
    }
    if (!whole || depth !== 0) break;
    pre += m[1]; post = m[4] + post; body = m[3];
  }
  let at = body.search(new RegExp('<(' + tags.join('|') + ')(?=[\\s>/])', 'i'));
  if (at < 0) return { pre, intro: body, rest: '', post, found: false };
  const before = body.slice(0, at);
  const lastP = before.search(/<p\b[^>]*>(?:(?!<p\b)[\s\S])*$/i);
  if (lastP >= 0) {
    const para = before.slice(lastP).trim();
    const words = para.replace(/<[^>]+>/g, '').trim();
    if (words.length <= 80 && (/:$/.test(words) || /^<p\b[^>]*>\s*<(strong|b)\b[\s\S]*<\/(strong|b)>\s*(<\/p>)?$/i.test(para))) at = lastP;
  }
  return { pre, intro: body.slice(0, at), rest: body.slice(at), post, found: true };
};

// Plain text to HTML: blank-line paragraphs, single line breaks, '- ' lines as a list
const toHtml = text => String(text || '').split(/\n\s*\n/).map(x => x.trim()).filter(Boolean).reduce((acc, para) => {
  const lines = para.split('\n').map(l => l.trim()).filter(Boolean);
  if (lines.every(l => /^[-*]\s+/.test(l))) {
    const lis = lines.map(l => '<li>' + esc(l.replace(/^[-*]\s+/, '')) + '</li>').join('');
    return acc.endsWith('</ul>') ? acc.slice(0, -5) + lis + '</ul>' : acc + '<ul>' + lis + '</ul>';
  }
  return acc + '<p>' + esc(para).replace(/\n/g, '<br>') + '</p>';
}, '');

// Replace only the intro: everything from the first heading, list or table down stays as it is
const parts = splitIntro(live, s.intro_ends_at);
const intro = toHtml(d.final_text);
return { json: { ...d,
  html: parts.pre + intro + (parts.rest ? '\n' + parts.rest : '') + parts.post,
  kept_sections: parts.found,
  url: product.onlineStoreUrl || product.onlineStorePreviewUrl || ''
} };

